<div class="page-heading"><div><div class="eyebrow">RESULTADOS FINANCEIROS</div><h1>Financeiro</h1><p>Receitas, despesas, vencimentos e caixa realizado.</p></div><div class="page-actions"><a href="<?=e(url('finance',['new'=>1]))?>#editor" class="btn-aurora"><?=svg_icon('plus',16)?> Novo lançamento</a></div></div>
<div class="stat-grid"><div class="stat-card"><div class="stat-icon"><?=svg_icon('wallet')?></div><div class="stat-title">Receitas recebidas</div><div class="stat-value"><?=e(money($totals['revenue']))?></div></div><div class="stat-card orange"><div class="stat-icon"><?=svg_icon('wallet')?></div><div class="stat-title">Despesas pagas</div><div class="stat-value"><?=e(money($totals['expenses']))?></div></div><div class="stat-card purple"><div class="stat-icon"><?=svg_icon('clock')?></div><div class="stat-title">A receber</div><div class="stat-value"><?=e(money($totals['receivable']))?></div></div><div class="stat-card blue"><div class="stat-icon"><?=svg_icon('calendar')?></div><div class="stat-title">A pagar</div><div class="stat-value"><?=e(money($totals['payable']))?></div></div></div>
<details class="panel editor" id="editor" <?=($edit||isset($_GET['new']))?'open':''?>><summary><?=$edit?'Editar lançamento':'Cadastrar lançamento'?></summary><div class="editor-inner"><form method="post" action="<?=e(url('finance.save'))?>"><?=csrf_field()?><input type="hidden" name="_back" value="finance"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-grid cols-3"><div class="field span-2"><label>Descrição *</label><input name="description" required value="<?=e($edit['description']??'')?>"></div><div class="field"><label>Tipo</label><select name="kind"><option value="income" <?=($edit['kind']??'')==='income'?'selected':''?>>Receita</option><option value="expense" <?=($edit['kind']??'expense')==='expense'?'selected':''?>>Despesa</option></select></div><div class="field"><label>Categoria *</label><input name="category" required value="<?=e($edit['category']??'Geral')?>"></div><div class="field"><label>Valor (R$) *</label><input name="amount" required type="number" step="0.01" min="0.01" value="<?=e($edit['amount']??'')?>"></div><div class="field"><label>Vencimento *</label><input name="due_date" required type="date" value="<?=e($edit['due_date']??date('Y-m-d'))?>"></div><div class="field"><label>Cliente (opcional)</label><select name="customer_id"><option value="">Não vinculado</option><?php foreach($clients as $c):?><option value="<?=e($c['id'])?>" <?=($edit['customer_id']??'')==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Projeto (opcional)</label><select name="project_id"><option value="">Não vinculado</option><?php foreach($projects as $p):?><option value="<?=e($p['id'])?>" <?=($edit['project_id']??'')==$p['id']?'selected':''?>><?=e($p['title'])?></option><?php endforeach;?></select></div></div><div class="form-footer"><button class="btn-aurora">Salvar lançamento</button><a href="<?=e(url('finance'))?>" class="btn-aurora btn-outline-aurora">Cancelar</a></div></form></div></details>
<div class="panel"><div class="panel-header"><div><h2>Lançamentos financeiros</h2><p>Pagamentos efetivos e títulos ainda em aberto</p></div><span class="tag"><?=count($transactions)?> lançamentos</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Descrição</th><th>Tipo</th><th>Valor</th><th>Vencimento</th><th>Situação</th><th>Cliente / Projeto</th><th>Ações</th></tr></thead><tbody><?php foreach($transactions as $t):?><tr><td><strong><?=e($t['description'])?></strong><small><?=e($t['category'])?></small></td><td><span class="status-badge <?=$t['kind']==='income'?'badge-success':'badge-danger'?>"><?=e(label_status($t['kind']))?></span></td><td><strong class="<?=$t['kind']==='income'?'text-accent':'text-danger-aurora'?>"><?=e(money($t['amount']))?></strong></td><td><?=e(date_br($t['due_date']))?></td><td><span class="status-badge <?=$t['paid_at']?'badge-success':'badge-muted'?>"><?=$t['paid_at']?'Pago':'Pendente'?></span></td><td><?=e($t['customer_name']??'—')?><small><?=e($t['project_title']??'')?></small></td><td><div class="table-actions"><a class="btn-aurora btn-outline-aurora btn-sm-aurora" href="<?=e(url('finance',['edit'=>$t['id']]))?>#editor"><?=svg_icon('edit',14)?></a><form method="post" action="<?=e(url('finance.paid'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($t['id'])?>"><button class="btn-aurora btn-sm-aurora <?=$t['paid_at']?'btn-outline-aurora':''?>"><?=$t['paid_at']?'Reabrir':'Baixar'?></button></form></div></td></tr><?php endforeach;?><?php if(!$transactions):?><tr><td colspan="7" class="empty">Nenhum lançamento.</td></tr><?php endif;?></tbody></table></div></div>
